-- Durable jobs/outbox: trigger writes share the originating D1 transaction.
-- Disabled on install; operator permits only isolated rehearsal dates.
CREATE TABLE diary_generation_control(singleton INTEGER PRIMARY KEY CHECK(singleton=1),enabled INTEGER NOT NULL DEFAULT 0,allowed_dates TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(allowed_dates)),config_version INTEGER NOT NULL DEFAULT 0,max_calls_per_day INTEGER NOT NULL DEFAULT 20 CHECK(max_calls_per_day BETWEEN 1 AND 200));
INSERT INTO diary_generation_control(singleton) VALUES(1);
CREATE TABLE diary_generation_jobs(user_id TEXT NOT NULL,date TEXT NOT NULL,generation INTEGER NOT NULL DEFAULT 1,saved_generation INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'queued',first_pending_at INTEGER,due_at INTEGER NOT NULL,lease_token TEXT,lease_until INTEGER,claimed_generation INTEGER,claimed_config INTEGER,claimed_edit INTEGER,attempts INTEGER NOT NULL DEFAULT 0,error_code TEXT,completed_at TEXT,saved_hash TEXT,input_hash TEXT,force_generation INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,date));
CREATE INDEX diary_generation_due ON diary_generation_jobs(status,due_at);
CREATE TABLE diary_generation_outbox(user_id TEXT NOT NULL,date TEXT NOT NULL,generation INTEGER NOT NULL,due_at INTEGER NOT NULL,sent_at INTEGER,PRIMARY KEY(user_id,date,generation));
CREATE TABLE diary_generation_attempts(token TEXT PRIMARY KEY,user_id TEXT NOT NULL,date TEXT NOT NULL,utc_date TEXT NOT NULL);
CREATE TABLE diary_entry_versions(user_id TEXT NOT NULL,date TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,date));
CREATE TABLE diary_generation_history(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,date TEXT NOT NULL,generation INTEGER NOT NULL,previous_entry TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX diary_history_day ON diary_generation_history(user_id,date,created_at DESC);
CREATE TRIGGER diary_gate_version AFTER UPDATE OF enabled,allowed_dates,max_calls_per_day ON diary_generation_control BEGIN UPDATE diary_generation_control SET config_version=config_version+1 WHERE singleton=1; END;
CREATE TRIGGER diary_config_user_ai_settings_insert AFTER INSERT ON user_ai_settings BEGIN UPDATE diary_generation_control SET config_version=config_version+1 WHERE singleton=1; END;
CREATE TRIGGER diary_config_user_ai_settings_update AFTER UPDATE ON user_ai_settings BEGIN UPDATE diary_generation_control SET config_version=config_version+1 WHERE singleton=1; END;
CREATE TRIGGER diary_config_user_ai_settings_delete AFTER DELETE ON user_ai_settings BEGIN UPDATE diary_generation_control SET config_version=config_version+1 WHERE singleton=1; END;
CREATE TRIGGER diary_config_user_ai_models_insert AFTER INSERT ON user_ai_models BEGIN UPDATE diary_generation_control SET config_version=config_version+1 WHERE singleton=1; END;
CREATE TRIGGER diary_config_user_ai_models_update AFTER UPDATE ON user_ai_models BEGIN UPDATE diary_generation_control SET config_version=config_version+1 WHERE singleton=1; END;
CREATE TRIGGER diary_config_user_ai_models_delete AFTER DELETE ON user_ai_models BEGIN UPDATE diary_generation_control SET config_version=config_version+1 WHERE singleton=1; END;
CREATE TRIGGER diary_config_user_ai_api_keys_insert AFTER INSERT ON user_ai_api_keys BEGIN UPDATE diary_generation_control SET config_version=config_version+1 WHERE singleton=1; END;
CREATE TRIGGER diary_config_user_ai_api_keys_update AFTER UPDATE ON user_ai_api_keys BEGIN UPDATE diary_generation_control SET config_version=config_version+1 WHERE singleton=1; END;
CREATE TRIGGER diary_config_user_ai_api_keys_delete AFTER DELETE ON user_ai_api_keys BEGIN UPDATE diary_generation_control SET config_version=config_version+1 WHERE singleton=1; END;
CREATE TRIGGER diary_config_user_ai_feature_settings_insert AFTER INSERT ON user_ai_feature_settings BEGIN UPDATE diary_generation_control SET config_version=config_version+1 WHERE singleton=1; END;
CREATE TRIGGER diary_config_user_ai_feature_settings_update AFTER UPDATE ON user_ai_feature_settings BEGIN UPDATE diary_generation_control SET config_version=config_version+1 WHERE singleton=1; END;
CREATE TRIGGER diary_config_user_ai_feature_settings_delete AFTER DELETE ON user_ai_feature_settings BEGIN UPDATE diary_generation_control SET config_version=config_version+1 WHERE singleton=1; END;
CREATE TRIGGER diary_entry_insert AFTER INSERT ON entries BEGIN INSERT INTO diary_entry_versions(user_id,date,revision) VALUES(NEW.user_id,NEW.date,1) ON CONFLICT(user_id,date) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER diary_entry_update AFTER UPDATE ON entries WHEN OLD.formatted_content IS NOT NEW.formatted_content OR OLD.summary IS NOT NEW.summary OR OLD.score IS NOT NEW.score OR OLD.score_details IS NOT NEW.score_details BEGIN INSERT INTO diary_entry_versions(user_id,date,revision) VALUES(NEW.user_id,NEW.date,1) ON CONFLICT(user_id,date) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER diary_entry_delete AFTER DELETE ON entries BEGIN INSERT INTO diary_entry_versions(user_id,date,revision) VALUES(OLD.user_id,OLD.date,1) ON CONFLICT(user_id,date) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER block_revision AFTER UPDATE ON blocks WHEN NEW.revision=OLD.revision
BEGIN UPDATE blocks SET revision=OLD.revision+1 WHERE id=NEW.id AND user_id=NEW.user_id; END;
CREATE TRIGGER diary_block_insert AFTER INSERT ON blocks BEGIN INSERT INTO diary_generation_jobs(user_id,date,due_at,first_pending_at)
 SELECT NEW.user_id,date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0))),unixepoch()+5,unixepoch() FROM diary_generation_control WHERE singleton=1 AND NEW.category='event' AND enabled=1 AND EXISTS(SELECT 1 FROM json_each(allowed_dates) WHERE value=date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0)))) AND COALESCE((SELECT enabled FROM user_ai_feature_settings WHERE user_id=NEW.user_id AND feature_key='diary_format'),1)=1
 ON CONFLICT(user_id,date) DO UPDATE SET generation=generation+1,status='queued',lease_token=NULL,lease_until=NULL,first_pending_at=COALESCE(first_pending_at,unixepoch()),due_at=min(unixepoch()+5,COALESCE(first_pending_at,unixepoch())+30),attempts=0,error_code=NULL;
 INSERT INTO diary_generation_outbox(user_id,date,generation,due_at) SELECT user_id,date,generation,due_at FROM diary_generation_jobs WHERE user_id=NEW.user_id AND date=date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0))) AND EXISTS(SELECT 1 FROM diary_generation_control WHERE singleton=1 AND NEW.category='event' AND enabled=1 AND EXISTS(SELECT 1 FROM json_each(allowed_dates) WHERE value=date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0)))) AND COALESCE((SELECT enabled FROM user_ai_feature_settings WHERE user_id=NEW.user_id AND feature_key='diary_format'),1)=1) ON CONFLICT(user_id,date,generation) DO NOTHING;
  END;
CREATE TRIGGER diary_block_delete AFTER DELETE ON blocks BEGIN INSERT INTO diary_generation_jobs(user_id,date,due_at,first_pending_at)
 SELECT OLD.user_id,date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0))),unixepoch()+5,unixepoch() FROM diary_generation_control WHERE singleton=1 AND OLD.category='event' AND enabled=1 AND EXISTS(SELECT 1 FROM json_each(allowed_dates) WHERE value=date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0)))) AND COALESCE((SELECT enabled FROM user_ai_feature_settings WHERE user_id=OLD.user_id AND feature_key='diary_format'),1)=1
 ON CONFLICT(user_id,date) DO UPDATE SET generation=generation+1,status='queued',lease_token=NULL,lease_until=NULL,first_pending_at=COALESCE(first_pending_at,unixepoch()),due_at=min(unixepoch()+5,COALESCE(first_pending_at,unixepoch())+30),attempts=0,error_code=NULL;
 INSERT INTO diary_generation_outbox(user_id,date,generation,due_at) SELECT user_id,date,generation,due_at FROM diary_generation_jobs WHERE user_id=OLD.user_id AND date=date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0))) AND EXISTS(SELECT 1 FROM diary_generation_control WHERE singleton=1 AND OLD.category='event' AND enabled=1 AND EXISTS(SELECT 1 FROM json_each(allowed_dates) WHERE value=date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0)))) AND COALESCE((SELECT enabled FROM user_ai_feature_settings WHERE user_id=OLD.user_id AND feature_key='diary_format'),1)=1) ON CONFLICT(user_id,date,generation) DO NOTHING;
  END;
CREATE TRIGGER diary_block_update AFTER UPDATE ON blocks WHEN OLD.content IS NOT NEW.content OR OLD.images IS NOT NEW.images OR OLD.occurred_at IS NOT NEW.occurred_at OR OLD.category IS NOT NEW.category OR OLD.is_done IS NOT NEW.is_done OR OLD.done_at IS NOT NEW.done_at OR OLD.due_at IS NOT NEW.due_at OR OLD.due_all_day IS NOT NEW.due_all_day BEGIN INSERT INTO diary_generation_jobs(user_id,date,due_at,first_pending_at)
 SELECT OLD.user_id,date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0))),unixepoch()+5,unixepoch() FROM diary_generation_control WHERE singleton=1 AND OLD.category='event' AND enabled=1 AND EXISTS(SELECT 1 FROM json_each(allowed_dates) WHERE value=date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0)))) AND COALESCE((SELECT enabled FROM user_ai_feature_settings WHERE user_id=OLD.user_id AND feature_key='diary_format'),1)=1
 ON CONFLICT(user_id,date) DO UPDATE SET generation=generation+1,status='queued',lease_token=NULL,lease_until=NULL,first_pending_at=COALESCE(first_pending_at,unixepoch()),due_at=min(unixepoch()+5,COALESCE(first_pending_at,unixepoch())+30),attempts=0,error_code=NULL;
 INSERT INTO diary_generation_outbox(user_id,date,generation,due_at) SELECT user_id,date,generation,due_at FROM diary_generation_jobs WHERE user_id=OLD.user_id AND date=date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0))) AND EXISTS(SELECT 1 FROM diary_generation_control WHERE singleton=1 AND OLD.category='event' AND enabled=1 AND EXISTS(SELECT 1 FROM json_each(allowed_dates) WHERE value=date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0)))) AND COALESCE((SELECT enabled FROM user_ai_feature_settings WHERE user_id=OLD.user_id AND feature_key='diary_format'),1)=1) ON CONFLICT(user_id,date,generation) DO NOTHING;
 INSERT INTO diary_generation_jobs(user_id,date,due_at,first_pending_at)
 SELECT NEW.user_id,date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0))),unixepoch()+5,unixepoch() FROM diary_generation_control WHERE singleton=1 AND NEW.category='event' AND enabled=1 AND EXISTS(SELECT 1 FROM json_each(allowed_dates) WHERE value=date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0)))) AND COALESCE((SELECT enabled FROM user_ai_feature_settings WHERE user_id=NEW.user_id AND feature_key='diary_format'),1)=1 AND (OLD.category<>'event' OR date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0)))<>date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0))))
 ON CONFLICT(user_id,date) DO UPDATE SET generation=generation+1,status='queued',lease_token=NULL,lease_until=NULL,first_pending_at=COALESCE(first_pending_at,unixepoch()),due_at=min(unixepoch()+5,COALESCE(first_pending_at,unixepoch())+30),attempts=0,error_code=NULL;
 INSERT INTO diary_generation_outbox(user_id,date,generation,due_at) SELECT user_id,date,generation,due_at FROM diary_generation_jobs WHERE user_id=NEW.user_id AND date=date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0))) AND EXISTS(SELECT 1 FROM diary_generation_control WHERE singleton=1 AND NEW.category='event' AND enabled=1 AND EXISTS(SELECT 1 FROM json_each(allowed_dates) WHERE value=date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0)))) AND COALESCE((SELECT enabled FROM user_ai_feature_settings WHERE user_id=NEW.user_id AND feature_key='diary_format'),1)=1 AND (OLD.category<>'event' OR date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0)))<>date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0))))) ON CONFLICT(user_id,date,generation) DO NOTHING;
  END;
